package gf16

import "github.com/klauspost/cpuid/v2"

//go:generate go run asmgen/main.go

// The arm64 backend is a port of ParPar's "CLMul (NEON)" / "CLMul (SHA3)"
// methods: carry-less multiplication with the 8-bit PMULL instruction (part of
// base AdvSIMD, so every arm64 CPU has it), optionally using the SHA3
// extension's EOR3 for three-way XORs. The kernels live in clmul_arm64.s,
// generated by asmgen/main.go, which also documents the math.

const (
	// clmulStride is the bytes consumed per kernel iteration: one 32-byte
	// block, 16 words, de-interleaved by LD2 into low-byte and high-byte rows.
	clmulStride = 32
	clmulAlign  = 32
)

// Kernel entry points (clmul_arm64.s). Every kernel writes dst[0:n]; n is a
// non-zero multiple of clmulStride; nsrc is in [1, maxPassRegions]. The Mul
// kernels read only srcs[0]/coeffs[0].

//go:noescape
func clmulMulAddNEON(dst *byte, srcs *srcPtrs, coeffs *coefList, nsrc, n int)

//go:noescape
func clmulMulAddSHA3(dst *byte, srcs *srcPtrs, coeffs *coefList, nsrc, n int)

//go:noescape
func clmulMulNEON(dst *byte, srcs *srcPtrs, coeffs *coefList, nsrc, n int)

//go:noescape
func clmulMulSHA3(dst *byte, srcs *srcPtrs, coeffs *coefList, nsrc, n int)

//go:noescape
func prepareBlocks(dst, src *byte, n int)

//go:noescape
func finishBlocks(dst, src *byte, n int)

//go:noescape
func xorBlocks(dst, src *byte, n int)

// Single-source wrappers. They call the assembly directly (not through a
// func value) so the stack arrays provably do not escape.

func mulNEON(dst, src *byte, n int, coeff uint16) {
	ptrs, cs := srcPtrs{src}, coefList{coeff}
	clmulMulNEON(dst, &ptrs, &cs, 1, n)
}

func mulAddNEON(dst, src *byte, n int, coeff uint16) {
	ptrs, cs := srcPtrs{src}, coefList{coeff}
	clmulMulAddNEON(dst, &ptrs, &cs, 1, n)
}

func mulSHA3(dst, src *byte, n int, coeff uint16) {
	ptrs, cs := srcPtrs{src}, coefList{coeff}
	clmulMulSHA3(dst, &ptrs, &cs, 1, n)
}

func mulAddSHA3(dst, src *byte, n int, coeff uint16) {
	ptrs, cs := srcPtrs{src}, coefList{coeff}
	clmulMulAddSHA3(dst, &ptrs, &cs, 1, n)
}

func init() {
	neon := &kernel{name: "CLMul (NEON)", stride: clmulStride, align: clmulAlign,
		mul: mulNEON, mulAdd: mulAddNEON, mulAddMulti: clmulMulAddNEON, xor: xorBlocks,
		prepare: prepareBlocks, finish: finishBlocks}
	if !cpuid.CPU.Supports(cpuid.SHA3) {
		registerKernels(neon, neon)
		return
	}
	sha3 := &kernel{name: "CLMul (SHA3)", stride: clmulStride, align: clmulAlign,
		mul: mulSHA3, mulAdd: mulAddSHA3, mulAddMulti: clmulMulAddSHA3, xor: xorBlocks,
		prepare: prepareBlocks, finish: finishBlocks}
	registerKernels(sha3, sha3, neon)
}
